"""Generate CATALOGUE.md from the registry: every dataset by data type."""

import sys
from collections import defaultdict
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from labobs import REPO_ROOT  # noqa: E402
from labobs.registry import load_registry  # noqa: E402

reg = load_registry()
by = defaultdict(list)
for s in reg.values():
    for d in s.datasets:
        by[d.domains[0]].append((s, d))

lines = ["# Dataset catalogue", "",
         "Generated by `scripts/catalogue.py` from `registry/sources/`. "
         "✓ = identifier confirmed against the publisher's documentation or a live response.", ""]
n = 0
for dom in sorted(by):
    lines += [f"## {dom}", "", "| Dataset | Publisher | Frequency | Also serves | ✓ |", "|---|---|---|---|---|"]
    for s, d in sorted(by[dom], key=lambda x: x[1].key):
        also = ", ".join(d.domains[1:])
        lines.append(f"| `{d.key}` — {d.title} | {s.publisher} | {d.frequency} | {also} | {'✓' if d.verified else ''} |")
        n += 1
    lines.append("")
lines.insert(3, f"{n} datasets from {len(reg)} sources.\n")
(REPO_ROOT / "CATALOGUE.md").write_text("\n".join(lines) + "\n")
print(f"{n} datasets")
